<?php

declare(strict_types=1);

/**
 * Render all English-learning JSON entries to individual Markdown pages
 * and build a combined alphabetical index in dictionary.md.
 *
 * Run from any working directory:
 *   php scripts/dictionary.php
 */

$root = dirname(__DIR__);
$indexFile = $root . '/dictionary.md';
$generatedMarker = '<!-- This file is generated by scripts/dictionary.php. Do not edit it manually. -->';
$generatedMarkers = [
    $generatedMarker,
    '<!-- This file is generated by scripts/word.php. Do not edit it manually. -->',
];

$collections = [
    'words' => [
        'label' => 'Word',
        'source' => $root . '/data/words',
        'output' => $root . '/dictionary',
        'term_key' => 'word',
        'type' => 'word',
    ],
    'phrasal_verbs' => [
        'label' => 'Phrasal verb',
        'source' => $root . '/data/phrasal_verbs',
        'output' => $root . '/phrasal_verbs',
        'term_key' => 'phrase',
        'type' => 'phrasal_verb',
    ],
    'collocations' => [
        'label' => 'Collocation',
        'source' => $root . '/data/collocations',
        'output' => $root . '/collocations',
        'term_key' => 'phrase',
        'type' => 'collocation',
    ],
    'idioms' => [
        'label' => 'Idiom',
        'source' => $root . '/data/idioms',
        'output' => $root . '/idioms',
        'term_key' => 'phrase',
        'type' => 'idiom',
    ],
    'readings' => [
        'label' => 'Reading',
        'source' => $root . '/data/readings',
        'output' => $root . '/readings',
        'term_key' => 'title',
        'type' => 'reading',
    ],
    'essays' => [
        'label' => 'IELTS Essay',
        'source' => $root . '/data/essays',
        'output' => $root . '/essays',
        'term_key' => 'title',
        'type' => 'essay',
    ],
    'letters' => [
        'label' => 'IELTS Letter',
        'source' => $root . '/data/letters',
        'output' => $root . '/letters',
        'term_key' => 'title',
        'type' => 'letter',
    ],
    'monologues' => [
        'label' => 'Monologue',
        'source' => $root . '/data/monologues',
        'output' => $root . '/monologues',
        'term_key' => 'title',
        'type' => 'monologue',
    ],
];

/**
 * Render a reading JSON document as a Markdown page.
 */
function renderReading(array $reading, string $generatedMarker): string
{
    $markdown = [
        '# ' . markdownText($reading['title']),
        '',
        $generatedMarker,
        '',
    ];

    $tags = is_array($reading['tags'] ?? null) ? $reading['tags'] : [];

    if ($tags !== []) {
        $markdown[] = '**Tags:** ' . implode(', ', array_map(
            static fn (mixed $tag): string => is_string($tag) ? markdownText($tag) : '',
            $tags
        ));
        $markdown[] = '';
    }

    $context = is_array($reading['context'] ?? null) ? $reading['context'] : [];

    foreach (['topic' => 'Topic', 'purpose' => 'Learning purpose'] as $key => $label) {
        $value = $context[$key] ?? '';

        if (is_string($value) && trim($value) !== '') {
            $markdown[] = '**' . $label . ':** ' . markdownText($value);
            $markdown[] = '';
        }
    }

    foreach (($reading['paragraphs'] ?? []) as $paragraph) {
        if (!is_array($paragraph)) {
            continue;
        }

        $sentenceTexts = [];
        $sentenceDetails = [];

        foreach (($paragraph['sentences'] ?? []) as $sentenceIndex => $sentence) {
            if (!is_array($sentence) || !is_string($sentence['text'] ?? null)) {
                continue;
            }

            $sentenceText = trim($sentence['text']);

            if ($sentenceText === '') {
                continue;
            }

            $sentenceTexts[] = $sentenceText;
            $sentenceNumber = count($sentenceTexts);
            $pronunciation = $sentence['pronunciation']['uk'] ?? '';

            if (is_string($pronunciation) && trim($pronunciation) !== '') {
                $sentenceDetails[] = '- **UK pronunciation (sentence ' . $sentenceNumber . '):** ' . markdownText($pronunciation);
            }

            foreach (is_array($sentence['notes'] ?? null) ? $sentence['notes'] : [] as $note) {
                if (is_string($note) && trim($note) !== '') {
                    $sentenceDetails[] = '- **Sentence ' . $sentenceNumber . ':** ' . markdownText($note);
                }
            }
        }

        if ($sentenceTexts !== []) {
            $markdown[] = implode(' ', $sentenceTexts);
            $markdown[] = '';
        }

        if ($sentenceDetails !== []) {
            $markdown[] = '**Sentence notes:**';
            $markdown = array_merge($markdown, $sentenceDetails);
            $markdown[] = '';
        }

        $paragraphNotes = renderBulletList($paragraph['notes'] ?? []);

        if ($paragraphNotes !== '') {
            $markdown[] = '**Paragraph notes:**';
            $markdown[] = $paragraphNotes;
            $markdown[] = '';
        }
    }

    appendList($markdown, 'Related materials', $reading['related'] ?? []);
    appendList($markdown, 'Notes', $reading['notes'] ?? []);

    return rtrim(implode("\n", $markdown)) . "\n";
}

/**
 * Render a single-speaker monologue as a Markdown page.
 */
function renderMonologue(array $entry, string $generatedMarker): string
{
    $context = is_array($entry['context'] ?? null) ? $entry['context'] : [];
    $speaker = is_array($entry['speaker'] ?? null) ? $entry['speaker'] : [];
    $markdown = ['# ' . markdownText($entry['title']), '', $generatedMarker, ''];

    $tags = is_array($entry['tags'] ?? null) ? $entry['tags'] : [];
    if ($tags !== []) {
        $markdown[] = '**Tags:** ' . implode(', ', array_map(
            static fn (mixed $tag): string => is_string($tag) ? markdownText($tag) : '',
            $tags
        ));
        $markdown[] = '';
    }

    foreach (['situation' => 'Situation', 'purpose' => 'Purpose', 'audience' => 'Audience'] as $key => $label) {
        $value = $context[$key] ?? '';
        if (is_string($value) && trim($value) !== '') {
            $markdown[] = '**' . $label . ':** ' . markdownText($value);
            $markdown[] = '';
        }
    }

    $speakerName = $speaker['name'] ?? '';
    if (is_string($speakerName) && trim($speakerName) !== '') {
        $markdown[] = '**Speaker:** ' . markdownText($speakerName);
        $markdown[] = '';
    }

    $markdown[] = '## Monologue';
    $markdown[] = '';
    $sentenceDetails = [];
    $sentenceNumber = 0;
    foreach (($entry['sentences'] ?? []) as $sentence) {
        if (!is_array($sentence) || !is_string($sentence['text'] ?? null) || trim($sentence['text']) === '') {
            continue;
        }
        $sentenceNumber++;
        $markdown[] = trim($sentence['text']);
        $markdown[] = '';
        $pronunciation = $sentence['pronunciation']['uk'] ?? '';
        if (is_string($pronunciation) && trim($pronunciation) !== '') {
            $sentenceDetails[] = '- **UK pronunciation (sentence ' . $sentenceNumber . '):** ' . markdownText($pronunciation);
        }
        foreach (is_array($sentence['notes'] ?? null) ? $sentence['notes'] : [] as $note) {
            if (is_string($note) && trim($note) !== '') {
                $sentenceDetails[] = '- **Sentence ' . $sentenceNumber . ':** ' . markdownText($note);
            }
        }
    }

    if ($sentenceDetails !== []) {
        $markdown[] = '## Sentence notes';
        $markdown[] = '';
        $markdown = array_merge($markdown, $sentenceDetails);
        $markdown[] = '';
    }

    appendList($markdown, 'Related materials', $entry['related'] ?? []);
    appendList($markdown, 'Notes', $entry['notes'] ?? []);
    return rtrim(implode("\n", $markdown)) . "\n";
}

/**
 * Render an IELTS essay or letter, including its task prompt and learning notes.
 */
function renderWriting(array $entry, string $generatedMarker, string $type): string
{
    $task = is_array($entry['task'] ?? null) ? $entry['task'] : [];
    $response = is_array($entry['response'] ?? null) ? $entry['response'] : [];
    $paragraphs = is_array($response['paragraphs'] ?? null) ? $response['paragraphs'] : [];
    $isLetter = $type === 'letter';
    $markdown = [
        '# ' . markdownText($entry['title']),
        '',
        $generatedMarker,
        '',
        '## IELTS task',
        '',
        '> ' . str_replace("\n", "\n> ", markdownText(is_string($task['prompt'] ?? null) ? $task['prompt'] : '')),
        '',
    ];

    $taskDetailKey = $isLetter ? 'tone' : 'question_type';
    $taskDetailLabel = $isLetter ? 'Tone' : 'Question type';
    $taskDetail = $task[$taskDetailKey] ?? '';

    if (is_string($taskDetail) && trim($taskDetail) !== '') {
        $markdown[] = '**' . $taskDetailLabel . ':** ' . markdownText($taskDetail);
        $markdown[] = '';
    }

    $markdown[] = $isLetter ? '## Model letter' : '## Model essay';
    $markdown[] = '';

    if ($isLetter) {
        $salutation = $response['salutation'] ?? '';
        if (is_string($salutation) && trim($salutation) !== '') {
            $markdown[] = markdownText($salutation);
            $markdown[] = '';
        }
    }

    foreach ($paragraphs as $paragraph) {
        if (is_string($paragraph) && trim($paragraph) !== '') {
            $markdown[] = markdownText($paragraph);
            $markdown[] = '';
        }
    }

    if ($isLetter) {
        $signOff = $response['sign_off'] ?? '';
        if (is_string($signOff) && trim($signOff) !== '') {
            $markdown[] = markdownText($signOff);
            $markdown[] = '';
        }
    }

    $wordCount = $response['word_count'] ?? null;
    if (is_int($wordCount) || (is_string($wordCount) && trim($wordCount) !== '')) {
        $markdown[] = '**Word count:** ' . markdownText((string) $wordCount);
        $markdown[] = '';
    }

    $writingNotes = is_array($entry['writing_notes'] ?? null) ? $entry['writing_notes'] : [];
    if ($writingNotes !== []) {
        $markdown[] = '## Writing notes';
        $markdown[] = '';
        foreach ($writingNotes as $note) {
            if (!is_array($note)) {
                continue;
            }
            $point = $note['point'] ?? '';
            $explanation = $note['explanation'] ?? '';
            if (!is_string($point) || trim($point) === '') {
                continue;
            }
            $line = '- **' . markdownText($point) . '**';
            if (is_string($explanation) && trim($explanation) !== '') {
                $line .= ': ' . markdownText($explanation);
            }
            $markdown[] = $line;
        }
        $markdown[] = '';
    }

    $keyLanguage = is_array($entry['key_language'] ?? null) ? $entry['key_language'] : [];
    if ($keyLanguage !== []) {
        $markdown[] = '## Key language';
        $markdown[] = '';
        foreach ($keyLanguage as $item) {
            if (!is_array($item)) {
                continue;
            }
            $expression = $item['expression'] ?? '';
            $meaning = $item['meaning_or_function'] ?? '';
            if (!is_string($expression) || trim($expression) === '') {
                continue;
            }
            $line = '- **' . markdownText($expression) . '**';
            if (is_string($meaning) && trim($meaning) !== '') {
                $line .= ' — ' . markdownText($meaning);
            }
            $markdown[] = $line;
        }
        $markdown[] = '';
    }

    appendList($markdown, 'Related materials', $entry['related'] ?? []);
    appendList($markdown, 'Notes', $entry['notes'] ?? []);

    return rtrim(implode("\n", $markdown)) . "\n";
}

/**
 * Write a generated file only when its contents differ.
 */
function writeIfChanged(string $path, string $content): bool
{
    if (is_file($path)) {
        $existingContent = file_get_contents($path);

        if ($existingContent === false) {
            fwrite(STDERR, "Could not read existing file: {$path}\n");
            return false;
        }

        if ($existingContent === $content) {
            return true;
        }
    }

    return file_put_contents($path, $content, LOCK_EX) !== false;
}

/**
 * Escape text for safe use in Markdown.
 */
function markdownText(string $value): string
{
    return str_replace(
        ["\\", '|', "\r", "\n"],
        ["\\\\", '\|', ' ', ' '],
        trim($value)
    );
}

/**
 * Format scalar and nested values used in grammar metadata.
 */
function grammarValue(mixed $value): string
{
    if (is_bool($value)) {
        return $value ? 'yes' : 'no';
    }

    if (is_scalar($value) || $value === null) {
        return (string) $value;
    }

    if (is_array($value)) {
        return implode(', ', array_map(
            static fn (mixed $item): string => is_scalar($item) || $item === null
                ? (string) $item
                : (string) json_encode($item, JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES),
            $value
        ));
    }

    return '';
}

/**
 * Render a grammar object as a compact inline list.
 */
function renderGrammar(mixed $grammar): string
{
    if (!is_array($grammar) || $grammar === []) {
        return '';
    }

    $items = [];

    foreach ($grammar as $key => $value) {
        $formattedValue = grammarValue($value);

        if ($formattedValue !== '') {
            $items[] = markdownText((string) $key) . ': ' . markdownText($formattedValue);
        }
    }

    return implode('; ', $items);
}

/**
 * Render a list of scalar strings as a Markdown bullet list.
 */
function renderBulletList(mixed $items): string
{
    if (!is_array($items)) {
        return '';
    }

    $lines = [];

    foreach ($items as $item) {
        if (is_string($item) && trim($item) !== '') {
            $lines[] = '- ' . markdownText($item);
        }
    }

    return implode("\n", $lines);
}

/**
 * Append a labelled list when it contains renderable values.
 */
function appendList(array &$markdown, string $label, mixed $items): void
{
    $list = renderBulletList($items);

    if ($list !== '') {
        $markdown[] = '**' . $label . ':**';
        $markdown[] = $list;
        $markdown[] = '';
    }
}

/**
 * Render examples as blockquotes.
 */
function appendExamples(array &$markdown, mixed $examples): void
{
    if (!is_array($examples)) {
        return;
    }

    foreach ($examples as $example) {
        if (is_string($example) && trim($example) !== '') {
            $markdown[] = '> ' . markdownText($example);
            $markdown[] = '';
        }
    }
}

/**
 * Render common metadata and notes for a meaning.
 */
function appendMeaningDetails(array &$markdown, array $meaning, bool $includeSynonyms = true): void
{
    if (isset($meaning['grammar'])) {
        $grammar = renderGrammar($meaning['grammar']);

        if ($grammar !== '') {
            $markdown[] = '**Grammar:** ' . $grammar;
            $markdown[] = '';
        }
    }

    appendExamples($markdown, $meaning['examples'] ?? []);

    if ($includeSynonyms) {
        foreach ([
            'synonyms' => 'Synonyms',
            'antonyms' => 'Antonyms',
            'collocations' => 'Collocations',
            'patterns' => 'Patterns',
            'notes' => 'Notes',
        ] as $field => $label) {
            appendList($markdown, $label, $meaning[$field] ?? []);
        }
    }
}

/**
 * Render a nested pattern with its structures, meanings, examples, and notes.
 */
function appendPattern(array &$markdown, array $pattern, int $patternNumber, bool $hasMeanings): void
{
    $structure = $pattern['structure'] ?? '';

    if (is_string($structure) && trim($structure) !== '') {
        $markdown[] = '#### Pattern ' . $patternNumber . ': ' . markdownText($structure);
        $markdown[] = '';
    }

    if ($hasMeanings) {
        foreach (($pattern['meanings'] ?? []) as $meaningIndex => $meaning) {
            if (!is_array($meaning)) {
                continue;
            }

            $definition = $meaning['meaning'] ?? '';

            if (is_string($definition) && trim($definition) !== '') {
                $markdown[] = '##### Meaning ' . ($meaningIndex + 1);
                $markdown[] = markdownText($definition);
                $markdown[] = '';
            }

            appendMeaningDetails($markdown, $meaning);
        }

        appendList($markdown, 'Pattern notes', $pattern['notes'] ?? []);
        return;
    }

    appendExamples($markdown, $pattern['examples'] ?? []);
    appendList($markdown, 'Pattern notes', $pattern['notes'] ?? []);
}

/**
 * Render one entry, using the appropriate structure for its type.
 */
function renderEntry(array $entry, string $type, string $termKey, string $generatedMarker): string
{
    $term = $entry[$termKey];
    $markdown = [
        '# ' . markdownText($term),
        '',
        $generatedMarker,
        '',
    ];

    $pronunciation = $entry['pronunciation']['uk'] ?? '';
    $tags = is_array($entry['tags'] ?? null) ? $entry['tags'] : [];

    if (is_string($pronunciation) && trim($pronunciation) !== '') {
        $markdown[] = '**Pronunciation (UK):** ' . markdownText($pronunciation);
        $markdown[] = '';
    }

    if ($tags !== []) {
        $markdown[] = '**Tags:** ' . implode(', ', array_map(
            static fn (mixed $tag): string => is_string($tag) ? markdownText($tag) : '',
            $tags
        ));
        $markdown[] = '';
    }

    if ($type === 'word') {
        foreach (($entry['parts_of_speech'] ?? []) as $part) {
            if (!is_array($part)) {
                continue;
            }

            $partOfSpeech = $part['part_of_speech'] ?? 'Other';
            $markdown[] = '## ' . ucfirst(markdownText(is_string($partOfSpeech) ? $partOfSpeech : 'Other'));
            $markdown[] = '';

            $grammar = renderGrammar($part['grammar'] ?? []);

            if ($grammar !== '') {
                $markdown[] = '**Grammar:** ' . $grammar;
                $markdown[] = '';
            }

            foreach (($part['meanings'] ?? []) as $meaningIndex => $meaning) {
                if (!is_array($meaning)) {
                    continue;
                }

                $definition = $meaning['meaning'] ?? '';

                if (!is_string($definition) || trim($definition) === '') {
                    continue;
                }

                $markdown[] = '### Meaning ' . ($meaningIndex + 1);
                $markdown[] = markdownText($definition);
                $markdown[] = '';
                appendMeaningDetails($markdown, $meaning);
            }

            appendList($markdown, 'Part-of-speech notes', $part['notes'] ?? []);
        }
    } elseif ($type === 'collocation') {
        foreach (($entry['patterns'] ?? []) as $patternIndex => $pattern) {
            if (!is_array($pattern)) {
                continue;
            }

            $structure = $pattern['structure'] ?? '';
            $markdown[] = '## Pattern ' . ($patternIndex + 1)
                . (is_string($structure) && trim($structure) !== '' ? ': ' . markdownText($structure) : '');
            $markdown[] = '';

            foreach (($pattern['meanings'] ?? []) as $meaningIndex => $meaning) {
                if (!is_array($meaning)) {
                    continue;
                }

                $definition = $meaning['meaning'] ?? '';

                if (is_string($definition) && trim($definition) !== '') {
                    $markdown[] = '### Meaning ' . ($meaningIndex + 1);
                    $markdown[] = markdownText($definition);
                    $markdown[] = '';
                }

                appendMeaningDetails($markdown, $meaning);
            }

            appendList($markdown, 'Pattern notes', $pattern['notes'] ?? []);
        }
    } else {
        foreach (($entry['meanings'] ?? []) as $meaningIndex => $meaning) {
            if (!is_array($meaning)) {
                continue;
            }

            $definition = $meaning['meaning'] ?? '';

            if (is_string($definition) && trim($definition) !== '') {
                $markdown[] = '## Meaning ' . ($meaningIndex + 1);
                $markdown[] = markdownText($definition);
                $markdown[] = '';
            }

            foreach (($meaning['patterns'] ?? []) as $patternIndex => $pattern) {
                if (is_array($pattern)) {
                    appendPattern($markdown, $pattern, $patternIndex + 1, false);
                }
            }

            foreach (['synonyms' => 'Synonyms', 'antonyms' => 'Antonyms', 'notes' => 'Notes'] as $field => $label) {
                appendList($markdown, $label, $meaning[$field] ?? []);
            }
        }
    }

    appendList($markdown, 'Related words and phrases', $entry['related'] ?? []);
    appendList($markdown, 'General notes', $entry['notes'] ?? []);

    return rtrim(implode("\n", $markdown)) . "\n";
}

$allEntries = [];
$expectedFilesByOutput = [];
$renderedCounts = [];

foreach ($collections as $collectionKey => $collection) {
    $sourceDirectory = $collection['source'];
    $outputDirectory = $collection['output'];
    $expectedFilesByOutput[$outputDirectory] = [];
    $renderedCounts[$collectionKey] = 0;

    if (!is_dir($outputDirectory)
        && !mkdir($outputDirectory, 0775, true)
        && !is_dir($outputDirectory)
    ) {
        fwrite(STDERR, "Could not create output directory: {$outputDirectory}\n");
        exit(1);
    }

    // A not-yet-created source directory is treated as an empty collection,
    // but existing output pages are not cleaned up until its source exists.
    if (!is_dir($sourceDirectory)) {
        continue;
    }

    $files = glob($sourceDirectory . '/*.json');

    if ($files === false) {
        fwrite(STDERR, "Could not read JSON files from: {$sourceDirectory}\n");
        exit(1);
    }

    foreach ($files as $file) {
        $json = file_get_contents($file);

        if ($json === false) {
            fwrite(STDERR, "Could not read file: {$file}\n");
            exit(1);
        }

        try {
            $entry = json_decode($json, true, 512, JSON_THROW_ON_ERROR);
        } catch (JsonException $exception) {
            fwrite(STDERR, sprintf(
                "Invalid JSON in %s: %s\n",
                $file,
                $exception->getMessage()
            ));
            exit(1);
        }

        $termKey = $collection['term_key'];

        if (
            !is_array($entry)
            || ($entry['type'] ?? null) !== $collection['type']
            || !isset($entry[$termKey])
            || !is_string($entry[$termKey])
            || trim($entry[$termKey]) === ''
        ) {
            fwrite(STDERR, "Invalid {$collection['type']} entry in: {$file}\n");
            exit(1);
        }

        $slug = pathinfo($file, PATHINFO_FILENAME);
        $relativePath = basename($outputDirectory) . '/' . $slug . '.md';
        $outputPath = $outputDirectory . '/' . $slug . '.md';
        $expectedFilesByOutput[$outputDirectory][] = $outputPath;

        if ($collection['type'] === 'reading') {
            $content = renderReading($entry, $generatedMarker);
        } elseif ($collection['type'] === 'monologue') {
            $content = renderMonologue($entry, $generatedMarker);
        } elseif (in_array($collection['type'], ['essay', 'letter'], true)) {
            $content = renderWriting($entry, $generatedMarker, $collection['type']);
        } else {
            $content = renderEntry($entry, $collection['type'], $termKey, $generatedMarker);
        }

        if (!writeIfChanged($outputPath, $content)) {
            fwrite(STDERR, "Could not write dictionary page: {$outputPath}\n");
            exit(1);
        }

        if (!in_array($collection['type'], ['reading', 'essay', 'letter', 'monologue'], true)) {
            $allEntries[] = [
                'label' => $collection['label'],
                'term' => $entry[$termKey],
                'path' => $relativePath,
                'sort' => strtolower($entry[$termKey]),
            ];
        }
        $renderedCounts[$collectionKey]++;
    }

    // Only remove stale generated pages when the corresponding source directory exists.
    foreach (glob($outputDirectory . '/*.md') ?: [] as $existingFile) {
        if (in_array($existingFile, $expectedFilesByOutput[$outputDirectory], true)) {
            continue;
        }

        $existingContent = file_get_contents($existingFile);

        if ($existingContent === false) {
            fwrite(STDERR, "Could not read existing page: {$existingFile}\n");
            exit(1);
        }

        foreach ($generatedMarkers as $marker) {
            if (str_contains($existingContent, $marker)) {
                if (!unlink($existingFile)) {
                    fwrite(STDERR, "Could not remove stale dictionary page: {$existingFile}\n");
                    exit(1);
                }
                break;
            }
        }
    }
}

usort($allEntries, static function (array $left, array $right): int {
    $labelComparison = strcmp($left['label'], $right['label']);

    if ($labelComparison !== 0) {
        return $labelComparison;
    }

    $comparison = strcasecmp($left['term'], $right['term']);

    return $comparison !== 0 ? $comparison : strcmp($left['term'], $right['term']);
});

$index = [
    '# English Dictionary',
    '',
    $generatedMarker,
    '',
    '| Type | Entry |',
    '| --- | --- |',
];

foreach ($allEntries as $entry) {
    $link = implode('/', array_map('rawurlencode', explode('/', $entry['path'])));
    $index[] = '| ' . $entry['label'] . ' | [' . markdownText($entry['term']) . '](' . $link . ') |';
}

$indexContent = rtrim(implode("\n", $index)) . "\n";

if (!writeIfChanged($indexFile, $indexContent)) {
    fwrite(STDERR, "Could not write dictionary index: {$indexFile}\n");
    exit(1);
}

printf(
    "Rendered %d word(s), %d phrasal verb(s), %d collocation(s), %d idiom(s), %d reading(s), %d essay(s), %d letter(s), and %d monologue(s); updated %s\n",
    $renderedCounts['words'],
    $renderedCounts['phrasal_verbs'],
    $renderedCounts['collocations'],
